INSERT IGNORE INTO `dc_bounty` (`id`, `title`, `description`, `class`, `category`, `urgent`, `status`, `created_at`) VALUES
(2, 'Barbarian Secondary skills', 'Use Hammer of the Ancients, Rend, Seismic Slam, Whirlwind and Ancient Spear, each with all 5 of its runes. Check the damage, the Fury cost, the area it hits and the rune effect match the tooltip and Diablo 3. Note any skill or rune that does nothing or something different.', 'Barbarian', 'skill', 0, 'open', FROM_UNIXTIME(1790826857)),
(3, 'Barbarian Defensive skills', 'Use Ground Stomp, Leap, Sprint and Ignore Pain, each with all 5 runes. Check the stun, movement, damage reduction and cooldown match the tooltip. Note anything that does nothing or lasts the wrong time.', 'Barbarian', 'skill', 0, 'open', FROM_UNIXTIME(1790826857)),
(4, 'Barbarian Might skills', 'Use Overpower, Revenge, Furious Charge and Avalanche, each with all 5 runes. Check the damage, cooldowns and procs (Revenge''s trigger, Furious Charge''s cooldown reduction) match the tooltip.', 'Barbarian', 'skill', 0, 'open', FROM_UNIXTIME(1790826857)),
(5, 'Barbarian Tactics skills', 'Use Threatening Shout, Battle Rage and War Cry, each with all 5 runes. Check the buff or debuff appears, lasts as long as the tooltip says, and changes your stats on the character sheet.', 'Barbarian', 'skill', 0, 'open', FROM_UNIXTIME(1790826857)),
(6, 'Barbarian Rage skills', 'Use Earthquake, Call of the Ancients and Wrath of the Berserker, each with all 5 runes. Check the damage, duration and cooldown. Known issue: Ancients'' kills give no loot (#88), so note anything else.', 'Barbarian', 'skill', 0, 'open', FROM_UNIXTIME(1790826857)),
(7, 'Barbarian passives, part 1', 'Equip the first 10 Barbarian passives (in the skills window''s order) one at a time and check each does what its tooltip says, on the sheet or in combat.', 'Barbarian', 'skill', 0, 'open', FROM_UNIXTIME(1790826857)),
(8, 'Barbarian passives, part 2', 'Equip the remaining Barbarian passives one at a time and check each does what its tooltip says, on the sheet or in combat. Nerves of Steel should lock out for 60 seconds after it triggers.', 'Barbarian', 'skill', 0, 'open', FROM_UNIXTIME(1790826857)),
(9, 'Barbarian Fury', 'Check Fury builds from Primary skills and when you take damage, drains slowly out of combat, and that every spender costs what its tooltip says. Watch the Fury globe while you play.', 'Barbarian', 'skill', 0, 'open', FROM_UNIXTIME(1790826857)),
(10, 'Wizard Primary skills', 'Use Magic Missile, Shock Pulse, Spectral Blade and Electrocute, each with all 5 runes. Check the damage, the Arcane Power each one gives or costs, and the rune effect match the tooltip.', 'Wizard', 'skill', 0, 'open', FROM_UNIXTIME(1790826857)),
(11, 'Wizard Secondary skills', 'Use Ray of Frost, Arcane Orb, Arcane Torrent and Disintegrate, each with all 5 runes. Check the damage, the Arcane Power cost, channeling and the rune effect match the tooltip.', 'Wizard', 'skill', 0, 'open', FROM_UNIXTIME(1790826857)),
(12, 'Wizard Defensive skills', 'Use Frost Nova, Diamond Skin, Slow Time and Teleport, each with all 5 runes. Check the freeze, shield, slow and teleport behave as the tooltip says, with the right cooldowns. Known: Teleport''s Reversal rune (#94).', 'Wizard', 'skill', 0, 'open', FROM_UNIXTIME(1790826857)),
(13, 'Wizard Force skills', 'Use Wave of Force, Energy Twister, Hydra, Meteor and Blizzard, each with all 5 runes. Check the damage, the area, the targeting circle size for Meteor and Blizzard, and the rune effects.', 'Wizard', 'skill', 0, 'open', FROM_UNIXTIME(1790826857)),
(14, 'Wizard Conjuration skills', 'Use Ice Armor, Storm Armor, Magic Weapon, Familiar and Energy Armor, each with all 5 runes. Check each buff appears, lasts, does its effect, and that only one armor is active at a time.', 'Wizard', 'skill', 0, 'open', FROM_UNIXTIME(1790826857)),
(15, 'Wizard Mastery skills', 'Use Explosive Blast, Mirror Image, Archon and Black Hole, each with all 5 runes. Check the damage, the images, Archon''s form and its skills, and Black Hole''s pull.', 'Wizard', 'skill', 0, 'open', FROM_UNIXTIME(1790826857)),
(16, 'Wizard passives, part 1', 'Equip the first 9 Wizard passives (in the skills window''s order) one at a time and check each does what its tooltip says, on the sheet or in combat.', 'Wizard', 'skill', 0, 'open', FROM_UNIXTIME(1790826857)),
(17, 'Wizard passives, part 2', 'Equip the remaining Wizard passives one at a time and check each does what its tooltip says, on the sheet or in combat.', 'Wizard', 'skill', 0, 'open', FROM_UNIXTIME(1790826857)),
(18, 'Wizard Arcane Power', 'Check Arcane Power regenerates, that every skill costs what its tooltip says, and that the right globe is the blue Wizard globe. Note any skill that costs nothing or too much.', 'Wizard', 'skill', 0, 'open', FROM_UNIXTIME(1790826857)),
(19, 'Wizard spellbook and tooltips', 'Open the spellbook and hover every Wizard skill and rune. Check the names, icons and tooltip text are right and readable, with no raw tokens like %d or {0}.', 'Wizard', 'client-patch', 0, 'open', FROM_UNIXTIME(1790826857)),
(20, 'Barbarian spellbook and tooltips', 'Open the spellbook and hover every Barbarian skill and rune. Check the names, icons and tooltip text are right and readable, with no raw tokens like %d or {0}.', 'Barbarian', 'client-patch', 0, 'open', FROM_UNIXTIME(1790826857)),
(21, 'Skills window and action bar', 'Pick skills, runes and passives in the skills window, then check they land on the right action-bar slots, survive a relog, and that Town Portal stays in slot 7.', 'Any', 'ui', 0, 'open', FROM_UNIXTIME(1790826857)),
(22, 'Skill cooldowns', 'Use several skills with cooldowns back to back. Each should run its own cooldown and not lock the others. Check the cooldown shown on the bar matches the tooltip.', 'Any', 'skill', 0, 'open', FROM_UNIXTIME(1790826857)),
(23, 'New character start', 'Make a brand-new Warrior and a brand-new Mage. Check each starts at level 70 with 200 Paragon and its start gear exactly once, logs in without hanging, and has two 22-slot Horadric Satchels.', 'Any', 'core', 0, 'open', FROM_UNIXTIME(1790826857)),
(24, 'Class creation', 'Try to create each class. Warrior and Mage should work; every other class should be refused with a clear message.', 'Any', 'core', 0, 'open', FROM_UNIXTIME(1790826857)),
(25, 'Character sheet and stats', 'Open the character sheet and check the stats read sensibly: main stat, damage, toughness, crit chance and damage, attack speed, armor, resistances, block. Equip and unequip items and check the numbers change.', 'Any', 'skill', 0, 'open', FROM_UNIXTIME(1790826857)),
(26, 'Movement speed and XP bonus', 'Equip gear with Movement Speed or Experience Bonus and check your speed and the XP you get actually change.', 'Any', 'loot', 0, 'open', FROM_UNIXTIME(1790826857)),
(27, 'Paragon points', 'Spend Paragon points in each tab. Check the bonuses apply on the sheet, your main stat goes to the right class stat, and the Paragon bar shows progress.', 'Any', 'skill', 0, 'open', FROM_UNIXTIME(1790826857)),
(28, 'Opening a Nephalem Rift', 'Open a rift from the obelisk. Check the opening plays out, you get into the rift, the progress bar fills as you kill, and the Rift Guardian spawns at 100%.', 'Any', 'rift', 0, 'open', FROM_UNIXTIME(1790826857)),
(29, 'Rift Guardian', 'Kill a Rift Guardian. Check it fights properly, drops its rewards, and the rift completes and lets you leave.', 'Any', 'rift', 0, 'open', FROM_UNIXTIME(1790826857)),
(30, 'Rift monsters don''t reset', 'In a rift, pull monsters far away, then run off. They should chase you and never reset or heal.', 'Any', 'enemy-ai', 0, 'open', FROM_UNIXTIME(1790826857)),
(31, 'Rift leaderboard', 'Finish a rift, then check your clear time shows on the website''s leaderboard.', 'Any', 'rift', 0, 'open', FROM_UNIXTIME(1790826857)),
(32, 'Difficulty tiers', 'Play rifts on several difficulties, Normal up to Torment VI. Check monsters get tougher and the XP and gold bonus goes up with each tier.', 'Any', 'rift', 0, 'open', FROM_UNIXTIME(1790826857)),
(33, 'Elite affixes, part 1', 'Fight Champion and Rare packs and note which affixes you meet: Arcane Enchanted, Molten, Frozen, Jailer, Waller, Fire Chains. Check each looks and works like Diablo 3.', 'Any', 'rift', 0, 'open', FROM_UNIXTIME(1790826857)),
(34, 'Elite affixes, part 2', 'Fight Champion and Rare packs and note which affixes you meet: Illusionist, Teleporter, Shielding, Avenger, Horde, Juggernaut, Health Link and the rest. Check each works like Diablo 3.', 'Any', 'rift', 0, 'open', FROM_UNIXTIME(1790826857)),
(35, 'Jailer and crowd control', 'Get held by a Jailer and frozen or stunned by elites. Check you see a debuff with a timer, and that it ends when it should.', 'Any', 'rift', 0, 'open', FROM_UNIXTIME(1790826857)),
(36, 'Fire Chains and Health Link beams', 'Find packs with Fire Chains or Health Link. Check the beams draw between the elites and Fire Chains hurts you when you cross it.', 'Any', 'rift', 0, 'open', FROM_UNIXTIME(1790826857)),
(37, 'Monster targeting', 'Play with a friend or near others. Check monsters pick and switch targets sensibly and don''t ignore or glue to one player.', 'Any', 'enemy-ai', 0, 'open', FROM_UNIXTIME(1790826857)),
(38, 'Corpse loot', 'Kill monsters and right-click their corpses. Check you see your own drops, can take them by click and by autoloot, and that an emptied corpse stops sparkling.', 'Any', 'loot', 0, 'open', FROM_UNIXTIME(1790826857)),
(39, 'Area looting', 'Kill a pack, then right-click one corpse. Check you get your drops from every corpse within about 30 yards, best items first, 16 per page.', 'Any', 'loot', 0, 'open', FROM_UNIXTIME(1790826857)),
(40, 'Corpse loot with two players', 'Kill a monster together. Each of you should see only your own drops, and looting at the same moment must not duplicate or lose anything. Needs two players.', 'Any', 'loot', 0, 'open', FROM_UNIXTIME(1790826857)),
(41, 'Group loot settings', 'In a group, try free for all, round robin, master looter, group loot and need before greed. Both of you can open the corpse and take your own drops every time. Needs two players.', 'Any', 'loot', 0, 'open', FROM_UNIXTIME(1790826857)),
(42, 'Area looting with two players', 'Kill a pack together, then each area-loot. You each get only your own drops, and a corpse your partner emptied still holds yours. Needs two players.', 'Any', 'loot', 0, 'open', FROM_UNIXTIME(1790826857)),
(43, 'Loot window paging', 'Get more than 16 drops in range (a big pack with area looting). Right-click again and check the next 16 show.', 'Any', 'loot', 0, 'open', FROM_UNIXTIME(1790826857)),
(44, 'Drops disappear with the corpse', 'Leave a drop on a corpse and wait for it to decay, or close the rift. The drop should be gone, and nothing should arrive by mail.', 'Any', 'loot', 0, 'open', FROM_UNIXTIME(1790826857)),
(45, 'Item drops', 'Play for a while and check drops are Diablo 3 items with sensible affixes, mostly for your class, and that legendaries drop unidentified. Note anything odd on an item.', 'Any', 'loot', 0, 'open', FROM_UNIXTIME(1790826857)),
(46, 'Gold', 'Pick up gold from kills and check the amounts and your total add up, including after a relog.', 'Any', 'loot', 0, 'open', FROM_UNIXTIME(1790826857)),
(47, 'Account stash', 'Move items into and out of the account stash with drag and drop, then check another character on the same account sees them. Nothing should be lost or duplicated.', 'Any', 'loot', 0, 'open', FROM_UNIXTIME(1790826857)),
(48, 'Inventory screen', 'Use the Torment inventory: equip, unequip, move, split stacks and drag items between bags and the stash. Note anything that won''t move or lands in the wrong place.', 'Any', 'ui', 0, 'open', FROM_UNIXTIME(1790826857)),
(49, 'Mystic re-enchant', 'At the Mystic, re-roll one affix on an item. Check the price and materials are shown first, the options make sense, and your choice sticks.', 'Any', 'crafting', 0, 'open', FROM_UNIXTIME(1790826857)),
(50, 'Jeweler sockets', 'Socket a gem into an item, try a second gem in the same socket (it should be refused), then have the Jeweler remove it. Also combine gems.', 'Any', 'crafting', 0, 'open', FROM_UNIXTIME(1790826857)),
(51, 'Blacksmith salvage and repair', 'At the Blacksmith, salvage items one at a time and in bulk by rarity, and repair your gear. Check you get the right materials and are charged the right gold.', 'Any', 'crafting', 0, 'open', FROM_UNIXTIME(1790826857)),
(52, 'Transmog', 'Use the Mystic''s transmog option and change an item''s look. Check the look sticks after a relog.', 'Any', 'crafting', 0, 'open', FROM_UNIXTIME(1790826857)),
(53, 'Class-only gear', 'As a Wizard, loot a Barbarian-only item and try to wear it (it should be refused), and the other way round.', 'Any', 'loot', 0, 'open', FROM_UNIXTIME(1790826857)),
(54, 'Health potion', 'Use the health potion in combat. Check it heals, goes on its own cooldown, and the cooldown shows.', 'Any', 'skill', 0, 'open', FROM_UNIXTIME(1790826857)),
(55, 'Health and resource globes', 'Check the health globe and your resource globe fill and drain correctly, and the health globe warns you at low health.', 'Any', 'ui', 0, 'open', FROM_UNIXTIME(1790826857)),
(56, 'Action-bar look', 'Check the action-bar icons sit inside their slots, line up with the bar art, and nothing overlaps or spills. Note your screen resolution.', 'Any', 'ui', 0, 'open', FROM_UNIXTIME(1790826857)),
(57, 'Tooltips and wording', 'Hover skills, items and buffs. Check times say seconds and minutes, nothing says Diablocraft, and no raw codes like %d show.', 'Any', 'client-patch', 0, 'open', FROM_UNIXTIME(1790826857)),
(58, 'Town Portal and hub', 'Use Town Portal from the field and from a rift, then come back. Check you land in the hub and can return.', 'Any', 'core', 0, 'open', FROM_UNIXTIME(1790826857)),
(59, 'Hub services', 'Visit every NPC in the hub (Blacksmith, Mystic, Jeweler, stash, rift obelisk, Tome of Identification) and check each opens and works.', 'Any', 'core', 0, 'open', FROM_UNIXTIME(1790826857)),
(60, 'Identify legendaries', 'Pick up an unidentified legendary and identify it at the Tome of Identification. Check it shows its stats afterwards.', 'Any', 'loot', 0, 'open', FROM_UNIXTIME(1790826857)),
(61, 'Launcher install and update', 'Install the game with the launcher from the website''s guide. Check it installs the patch and addons, updates itself, and shows the patch notes and realm status.', 'Any', 'client-patch', 0, 'open', FROM_UNIXTIME(1790826857)),
(62, 'Launcher bug report', 'Send a bug report through the launcher''s form and check it arrives (staff will confirm).', 'Any', 'client-patch', 0, 'open', FROM_UNIXTIME(1790826857)),
(63, 'Website account', 'Sign up on the website, confirm your email, log in, reset your password once, and check your characters show on your account page.', 'Any', 'core', 0, 'open', FROM_UNIXTIME(1790826857)),
(64, 'Lua errors', 'Play normally with Lua errors shown (/console scriptErrors 1). Report any error popup with its text and what you were doing.', 'Any', 'ui', 0, 'open', FROM_UNIXTIME(1790826857)),
(65, 'End-to-end play', 'Play one full session as a new player: make a character, set up skills, do several rifts, loot, craft, and stash. Note everything that felt wrong or unlike Diablo 3.', 'Any', 'core', 0, 'open', FROM_UNIXTIME(1790826857));
